INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1560', 'お隣の天使様にいつの間にか駄目人間にされていた件', '2023年冬', 'PR0019', 'TVシリーズ', 12, '『お隣の天使様にいつの間にか駄目人間にされていた件』（おとなりのてんしさまにいつのまにかだめにんげんにされていたけん、英:The Angel Next Door Spoils Me Rotten）は、佐伯さんによる日本のライトノベル。小説家になろうにて、2018年12月から連載されている。書籍版はGA文庫（SBクリエイティブ）より2019年6月から刊行されており、イラストは1巻販売時は和武はざのが', 143338) ON CONFLICT DO NOTHING;
