INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1563', 'Buddy Daddies', '2023年冬', 'PR0083', 'TVシリーズ', 12, '『Buddy Daddies』（バディ・ダディズ）はP.A.WORKS制作による日本のテレビアニメ。2022年10月22日に制作発表され、2023年1月から4月までTOKYO MXほかにて放送された。', 155907) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1564', 'NieR:Automata Ver1.1a', '2023年冬', 'PR0001', 'TVシリーズ', 12, NULL, 145665) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1565', 'とんでもスキルで異世界放浪メシ', '2023年冬', 'PR0023', 'TVシリーズ', 12, '『とんでもスキルで異世界放浪メシ』（とんでもスキルでいせかいほうろうメシ、英題:Campfire Cooking in Another World with My Absurd Skill）は、江口連による日本のライトノベル。略称は「とんスキ」。 『小説家になろう』にて2016年1月から連載を開始し、オーバーラップノベルス（オーバーラップ）より、同年11月から刊行されている。イラストは雅が担当して', 156067) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1566', '異世界のんびり農家', '2023年冬', 'PR0059', 'TVシリーズ', 12, '『異世界のんびり農家』（いせかいのんびりのうか）は、内藤騎之介による日本のライトノベルおよびそれを原作とするメディアミックス作品。2016年12月29日より『小説家になろう』にて連載されている。2017年10月30日より加筆と修正を加えた書籍版がKADOKAWA（エンターブレイン）より刊行されている。書籍版のイラストはやすもが担当している。2026年7月時点で電子版を含めたシリーズ累計部数は600', 146850) ON CONFLICT DO NOTHING;
