INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1571', '久保さんは僕を許さない', '2023年冬', 'PR0027', 'TVシリーズ', 12, '『久保さんは僕を許さない』（くぼさんはモブをゆるさない）は、雪森寧々による日本の漫画作品。集英社の連載権争奪企画「シンマンGP2019」にて連載権を獲得。『週刊ヤングジャンプ』（同社）にて、2019年47号より2023年14号まで連載。『少年ジャンプ+』（同社）でも2020年8月12日より配信されている。2025年12月時点で単行本の累計発行部数は250万部を突破している。話数カウントは「epis', 148969) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1572', '氷属性男子とクールな同僚女子', '2023年冬', 'PR0059', 'TVシリーズ', 12, '『氷属性男子とクールな同僚女子』（こおりぞくせいだんしとクールなどうりょうじょし）は、殿ヶ谷美由記による日本の漫画作品。『ガンガンpixiv』（スクウェア・エニックス）にて、2019年7月13日から連載中。雪女の末裔とその同僚のクールな女子によるラブコメディを描く。2022年6月時点で単行本のシリーズ累計部数は50万部を突破している。', 151252) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1573', '転生王女と天才令嬢の魔法革命', '2023年冬', 'PR0100', 'TVシリーズ', 12, '『転生王女と天才令嬢の魔法革命』（てんせいおうじょとてんさいれいじょうのまほうかくめい）は、鴉ぴえろによる日本のライトノベル、およびメディアミックス作品。イラストはきさらぎゆりが担当している。略称は「転天」。2024年9月時点で電子版を含めたシリーズ累計部数は100万部を突破している。 「魔法に愛されなかった異端の天才」アニスフィアと、「誰よりも魔法に愛された天才」ユフィリアの、二人を主人公とする', 153629) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1574', '痛いのは嫌なので防御力に極振りしたいと思います。2', '2023年冬', 'PR0024', 'TVシリーズ', 12, NULL, 116867) ON CONFLICT DO NOTHING;
