INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1576', '冰剣の魔術師が世界を統べる', '2023年冬', 'PR0053', 'TVシリーズ', 12, '『冰剣の魔術師が世界を統べる〜世界最強の魔術師である少年は、魔術学院に入学する〜』（ひょうけんのまじゅつしがせかいをすべる せかいさいきょうのまじゅつしであるしょうねんは まじゅつがくいんににゅうがくする）は、御子柴奈々による日本のライトノベル作品。「小説家になろう」にて2019年10月25日より連載されており、2020年7月2日からは講談社ラノベ文庫（講談社）より刊行されている。イラストは梱枝り', 148116) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1577', '便利屋斎藤さん、異世界に行く', '2023年冬', 'PR0091', 'TVシリーズ', 12, '『便利屋斎藤さん、異世界に行く』（べんりやさいとうさん、いせかいにいく）は、一智和智による日本の漫画作品。『ComicWalker』（KADOKAWA）を中心にニコニコ静画などのweb漫画サイトにて連載中。2023年6月時点でシリーズ累計部数は80万部を超えている。', 144092) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1578', 'お兄ちゃんはおしまい！', '2023年冬', 'PR0045', 'TVシリーズ', 12, NULL, 147864) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1579', 'スパイ教室', '2023年冬', 'PR0125', 'TVシリーズ', 12, '『スパイ教室』（スパイきょうしつ、英題：SPY ROOM）は、竹町による日本のライトノベル。イラストはトマリ（本編・短編集）と我美蘭（スピンオフ）。ファンタジア文庫（KADOKAWA）より2020年1月から刊行されている。第32回ファンタジア大賞大賞受賞作。2025年11月時点で電子版を含めた全世界関連シリーズの累計部数は200万部を突破している。 メディアミックスとして、せうかなめ（1・3・4部', 146323) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1580', '解雇された暗黒兵士（30代）のスローなセカンドライフ', '2023年冬', NULL, 'TVシリーズ', 12, '『解雇された暗黒兵士（30代）のスローなセカンドライフ』（かいこされたあんこくへいしさんじゅうだいのスローなセカンドライフ）は、岡沢六十四による日本のライトノベル作品。「小説家になろう」にて2018年11月15日から2020年7月30日にかけて連載され、2019年8月2日からはKラノベブックス（講談社）より刊行されている。イラストはsage・ジョー。魔王軍から突然解雇され、流れ着いた人間の村で第二', 152523) ON CONFLICT DO NOTHING;
