INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1588', 'ツンデレ悪役令嬢リーゼロッテと実況の遠藤くんと解説の小林さん', '2023年冬', 'PR0061', 'TVシリーズ', 12, '『ツンデレ悪役令嬢リーゼロッテと実況の遠藤くんと解説の小林さん』（ツンデレあくやくれいじょうリーゼロッテとじっきょうのえんどうくんとかいせつのこばやしさん）は、恵ノ島すずによる日本のライトノベル。略称は「ツンリゼ」。「小説家になろう」にて2018年8月から11月まで連載されており、2019年4月にカドカワBOOKS（KADOKAWA）より書籍化された。イラストはえいひが担当している。2019年12', 143064) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1589', 'REVENGER', '2023年冬', 'PR0004', 'TVシリーズ', 12, '『REVENGER』（リベンジャー）は、亜細亜堂制作による日本のテレビアニメ。2022年9月30日に制作が発表され、TOKYO MXほかにて2023年1月から3月まで放送された。 ニトロプラスと松竹が手がけるオリジナルアニメ作品であり、ストーリー原案・シリーズ構成をニトロプラス所属の虚淵玄が務めた。', 155202) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1590', 'あやかしトライアングル', '2023年冬', 'PR0064', 'TVシリーズ', 12, '『あやかしトライアングル』（AYAKASHI TRIANGLE）は、矢吹健太朗による日本の漫画。『週刊少年ジャンプ』（集英社）において、2020年28号から2022年20号まで連載後、『少年ジャンプ+』（同）に移籍して2022年4月25日から2023年9月25日まで連載された。2022年1月時点で累計発行部数は100万部を突破している。', 142849) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1591', 'もののがたり', '2023年冬', 'PR0114', 'TVシリーズ', 12, '『もののがたり』は、オニグンソウによる日本の漫画。『ミラクルジャンプ』（集英社）にて、2014年5月号から2016年1月号まで連載された。その後掲載誌を『ウルトラジャンプ』（集英社）に移し、2016年2月号から2023年7月号まで連載。', 141785) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1592', '大雪海のカイナ', '2023年冬', 'PR0069', 'TVシリーズ', 11, '『大雪海のカイナ』（おおゆきうみのカイナ） は、日本のテレビアニメ作品。フジテレビ「+Ultra」ほかにて、2023年1月から3月まで放送された。 2023年10月13日、劇場版『大雪海のカイナ ほしのけんじゃ』が公開された。', 144144) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1593', '火狩りの王', '2023年冬', 'PR0040', 'TVシリーズ', 10, '『火狩りの王』（ひかりのおう）は、日向理恵子による日本の小説シリーズ。2018年から2021年までほるぷ出版より刊行された。 「火」をテーマとし、人類最終戦争後の世界が舞台となる長編ファンタジー作品として描かれる。', 125869) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1594', 'ツルネ －つながりの一射－', '2023年冬', 'PR0062', 'TVシリーズ', 13, NULL, 153841) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1595', 'アルスの巨獣', '2023年冬', 'PR0012', 'TVシリーズ', 12, '『アルスの巨獣』（アルスのきょじゅう）は、DMM.comおよび旭プロダクション企画による日本のテレビアニメ。2022年9月27日に制作が発表され、2023年1月から3月まで毎日放送・TBS系列『スーパーアニメイズム』枠ほかにて放送された。国外でも展開され、センタイ・フィルムワークスがアジア域外でのライセンスを受けている。', 155089) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1596', 'ノケモノたちの夜', '2023年冬', 'PR0095', 'TVシリーズ', 13, '『ノケモノたちの夜』（ノケモノたちのよる）は、星野真による日本の漫画作品。『週刊少年サンデー』（小学館）にて、2019年36・37合併号から2021年20号まで連載された。19世紀末のロンドンを舞台に、孤児の少女と悪魔を中心に描いた作品。 2022年6月にはテレビアニメ化が発表された。これに伴い、最速放送日の2023年1月8日より『ノケモノたちの夜 フレイムナイト』が「サンデーうぇぶり」（同）にて', 151679) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1597', 'The Legend of Heroes 閃の軌跡 Northern War', '2023年冬', 'PR0162', 'TVシリーズ', 12, NULL, 130696) ON CONFLICT DO NOTHING;
