INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1605', 'UniteUp!', '2023年冬', 'PR0046', 'TVシリーズ', 12, 'UniteUp!（ユナイトアップ）は、ソニー・ミュージックグループが贈る多次元アイドルプロジェクト。 2021年11月10日より開設されたUniteUp!公式YouTubeチャンネルでは、様々なアーティストの楽曲が公開されている。 テレビアニメは第1期が2023年1月から4月まで、第2期が2025年1月から4月までTOKYO MXほかにて放送された。', 154969) ON CONFLICT DO NOTHING;
