INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1608', '地獄楽', '2023年春', 'PR0023', 'TVシリーズ', 13, '『地獄楽』（じごくらく）は、賀来ゆうじによる日本の漫画。『少年ジャンプ+』（集英社、以下『J+』）において、2018年1月22日から2021年1月25日まで毎週月曜更新で連載された。', 128893) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1609', '【推しの子】', '2023年春', 'PR0051', 'TVシリーズ', 11, '『【推しの子】』（おしのこ）は、赤坂アカ×横槍メンゴによる日本の漫画、およびそれを原作としたアニメ、ドラマ、映画、演劇。『週刊ヤングジャンプ』（集英社）において、2020年21号から2024年50号まで連載された。1週遅れで『少年ジャンプ+』（集英社）においても毎週木曜更新で連載された。', 150672) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1610', 'マッシュル-MASHLE-', '2023年春', 'PR0001', 'TVシリーズ', 12, '『マッシュル-MASHLE-』は、甲本一による日本の漫画。『週刊少年ジャンプ』（集英社）において、2020年9号より2023年31号まで連載された。甲本にとって初めての連載作品である。 本作は魔法が身分を左右する世界「魔法界」を舞台に、魔法を使えないながらも鍛えられた肉体を持つ主人公、マッシュ・バーンデッドが活躍する物語である。本作は、サブタイトルに「●●と○○」（例：「マッシュ・バーンデッドと○', 151801) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1611', '天国大魔境', '2023年春', 'PR0043', 'TVシリーズ', 13, '『天国大魔境』（てんごくだいまきょう）は、石黒正数による日本の漫画作品。『月刊アフタヌーン』（講談社）にて、2018年3月号から連載中。文明崩壊後の日本を生きる少年少女達にまつわる謎を描くポストアポカリプスSF漫画。「このマンガがすごい！2019」にてオトコ編第1位にランクインした。2026年2月までに累計発行部数は230万部を突破している。 2023年4月からテレビアニメが放送し、「Anime', 155783) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1612', '山田くんとLv999の恋をする', '2023年春', 'PR0089', 'TVシリーズ', 13, '『山田くんとLv999の恋をする』（やまだくんとレベルきゅうひゃくきゅうじゅうきゅうのこいをする）は、ましろによる日本の漫画作品。 『GANMA!』（コミックスマート）において、2019年3月7日から連載中。単行本はKADOKAWAより刊行。本作はましろの初連載作品である。 2025年9月時点で単行本の累計発行部数（紙・電子版合算）が650万部を突破している。 2025年に実写映画版が公開。', 154965) ON CONFLICT DO NOTHING;
