INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1616', 'かぐや様は告らせたい -ファーストキッスは終わらない-', '2023年春', 'PR0001', 'TVシリーズ', 4, NULL, 151384) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1617', 'スキップとローファー', '2023年春', 'PR0083', 'TVシリーズ', 12, '『スキップとローファー』は、高松美咲による日本の漫画作品。『月刊アフタヌーン』（講談社）にて、2018年10月号から連載されている。2026年3月時点で紙と電子書籍を合わせた国内の累計部数は420万部を突破している。 マンガ大賞2020の第3位に選出された。2023年5月には第47回講談社漫画賞総合部門を受賞した。 メディアミックスとして、テレビアニメの第1期が2023年4月から6月まで放送された', 141911) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1618', 'この素晴らしい世界に爆焔を！', '2023年春', 'PR0031', 'TVシリーズ', 12, NULL, 150075) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1619', '君は放課後インソムニア', '2023年春', 'PR0058', 'TVシリーズ', 13, '『君は放課後インソムニア』（きみはほうかごインソムニア、英: Insomniacs after school）は、オジロマコトによる日本の漫画作品。略称は「君ソム」。『ビッグコミックスピリッツ』（小学館）にて2019年25号から2023年38号まで連載された。石川県七尾市を舞台に、不眠症（英: insomnia）という悩みを共有する高校生の男女の交流を、天文部の活動を通して描く青春漫画。作中で主人', 143653) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1620', 'デッドマウント・デスプレイ', '2023年春', 'PR0057', 'TVシリーズ', 12, '『デッドマウント・デスプレイ』（DEAD MOUNT DEATH PLAY）は、原作：成田良悟、作画：藤本新太による日本の漫画作品。『ヤングガンガン』（スクウェア・エニックス）にて、2017年21号から連載中。略称は「DMDP」。2022年11月時点で単行本の累計発行部数は55万部以上を記録している。単行本に収録されている書下ろし小説で、主人公である屍神殿の去った後の異世界側の話も同時進行している', 157198) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1621', 'トニカクカワイイ（シーズン2）', '2023年春', 'PR0007', 'TVシリーズ', 12, NULL, 141208) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1622', '神無き世界のカミサマ活動', '2023年春', NULL, 'TVシリーズ', 12, '『神無き世界のカミサマ活動』（かみなきせかいのカミサマかつどう）は、原作：朱白あおい、作画：半月板損傷による日本の漫画。略称は「カミカツ」。『月刊ヒーローズ』（ヒーローズ）にて、2019年6月号より連載を開始し、同誌が2020年12月号の刊行後には2020年11月27日より連載作品がウェブコミック配信サイト『コミプレ』（同）に移行となったため、本作も同サイトの『わいるどヒーローズ』レーベルにて連載', 148048) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1623', '転生貴族の異世界冒険録 〜自重を知らない神々の使徒〜', '2023年春', 'PR0165', 'TVシリーズ', 12, NULL, 153332) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1624', '彼女が公爵邸に行った理由', '2023年春', 'PR0104', 'TVシリーズ', 12, '『彼女が公爵邸に行った理由』（かのじょがこうしゃくていにいったりゆう、韓: 그녀가 공작저로 가야 했던 사정、英: THE REASON WHY RAELIANA ENDED UP AT THE DUKE''S MANSION）は、Milchaによる韓国の小説およびこれを原作とする漫画（ウェブトゥーン）作品。韓国ではカカオページで2016年9月19日から2018年6月18日まで小説として発表された', 151847) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1625', 'おとなりに銀河', '2023年春', 'PR0012', 'TVシリーズ', 12, '『おとなりに銀河』（おとなりにぎんが）は、雨隠ギドによる日本の漫画作品。『good!アフタヌーン』（講談社）にて、2020年5号から2023年6号まで連載。「完結までのご愛読に感謝」という理由により、2023年7号に番外編が掲載された。少女漫画家と正体が異種族の姫であるアシスタントが「婚姻関係の契り」を結んだところから展開が描かれるSFラブコメディ。 2023年4月から、本作を原作とするテレビドラ', 148098) ON CONFLICT DO NOTHING;
