INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1630', '女神のカフェテラス', '2023年春', 'PR0061', 'TVシリーズ', 12, '『女神のカフェテラス』（めがみのカフェテラス）は、瀬尾公治による日本の漫画作品。『週刊少年マガジン』（講談社）にて、2021年12号から2025年49号まで連載された。', 154412) ON CONFLICT DO NOTHING;
