INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1632', 'マイホームヒーロー', '2023年春', 'PR0061', 'TVシリーズ', 12, '『マイホームヒーロー』は、山川直輝（原作）、朝基まさし（作画）による日本の漫画。『週刊ヤングマガジン』（講談社）にて、2017年26号から2024年35号まで連載された。2024年10月時点での単行本累計発行部数は440万部を突破している。 ごく平凡な中年サラリーマン鳥栖哲雄の一家が、莫大な遺産を相続する予定であることを聞きつけた半グレ組織に目を付けられ、犯罪に巻き込まれていくクライム・サスペンス', 151189) ON CONFLICT DO NOTHING;
