INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1636', '贄姫と獣の王', '2023年春', 'PR0006', 'TVシリーズ', 24, '『贄姫と獣の王』（にえひめとけもののおう、英文表記: Sacrificial Princess and the King of Beasts）は、友藤結による日本の少女漫画作品。 『花とゆめ』（白泉社）の2015年17号に読切作品が掲載され、それが好評だったことから、同年23号から2020年22号まで連載された。コミックスに関しては、花とゆめコミックスレーベルに加えて、英語訳版がニューヨークのエン', 128715) ON CONFLICT DO NOTHING;
