INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1645', 'カワイスギクライシス', '2023年春', 'PR0063', 'TVシリーズ', 12, '『カワイスギクライシス』は、城戸みつるによる日本の漫画。『ジャンプスクエア』（集英社）にて、2019年11月号から毎号2話連載中。2021年7月から2024年10月の第122話までは同社の『少年ジャンプ＋』でも並行して火曜日に掲載されていた。 メディアミックスとして、テレビアニメが2023年4月から6月まで放送された。', 155070) ON CONFLICT DO NOTHING;
