INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1647', 'アイドルマスター シンデレラガールズ U149', '2023年春', 'PR0033', 'TVシリーズ', 12, '『アイドルマスター シンデレラガールズ U149』（アイドルマスター シンデレラガールズ ユーいちよんきゅう）（THE IDOLM@STER CINDERELLA GIRLS U149）は、原作：バンダイナムコエンターテインメント、作画：廾之によるソーシャルゲーム『アイドルマスター シンデレラガールズ』の漫画化作品。 2024年現在、『サイコミ』連載作の中では最も連載期間が長い漫画。 タイトルの（', 146975) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1648', 'THE MARGINAL SERVICE', '2023年春', NULL, 'TVシリーズ', 12, '『THE MARGINAL SERVICE』（ザ・マージナルサービス）は、3Hz制作による日本のテレビアニメ。2022年11月10日に制作発表され、2023年4月から6月まで日本テレビほかにて放送された。', 156854) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1649', 'ワールドダイスター', '2023年春', 'PR0003', 'TVシリーズ', 12, '『ワールドダイスター』（英語: World Dai Star）は、日本のメディアミックスプロジェクト。 バンダイナムコフィルムワークスの新規IPによる「“演劇”ガールズ」プロジェクト。2022年11月にプロジェクトが発表され、アニメとゲームアプリを主軸として展開される。 2023年4月から6月までテレビアニメが放送された。2023年7月よりゲームアプリ『ワールドダイスター 夢のステラリウム』の配信', 157765) ON CONFLICT DO NOTHING;
