INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1664', 'わたしの幸せな結婚', '2023年夏', 'PR0042', 'TVシリーズ', 12, '『わたしの幸せな結婚』（わたしのしあわせなけっこん）は、顎木あくみによる日本の小説。「小説家になろう」にて投稿されたオンライン小説であり、富士見L文庫（KADOKAWA）より書籍化され2019年1月から刊行されている。書籍版のイラストは月岡月穂。略称は「わた婚」。2024年12月時点で電子書籍・コミック含むシリーズ累計部数は900万部を突破している。 メディアミックスとしては、高坂りとによるコミカ', 147103) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1665', 'BLEACH 千年血戦篇-訣別譚-', '2023年夏', 'PR0035', 'TVシリーズ', 13, NULL, 159322) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1666', '好きな子がめがねを忘れた', '2023年夏', 'PR0118', 'TVシリーズ', 13, '『好きな子がめがねを忘れた』（すきなこがめがねをわすれた）は、藤近小梅による日本の漫画作品。略称は「好きめが」。作者がTwitterで発表した後、『月刊ガンガンJOKER』（スクウェア・エニックス）にて、2018年12月号より2024年5月号まで連載。 2019年次にくるマンガ大賞コミック部門12位。 2023年7月から9月までテレビアニメが放送された。', 160188) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1667', '夢見る男子は現実主義者', '2023年夏', 'PR0112', 'TVシリーズ', 12, '『夢見る男子は現実主義者』（ゆめみるだんしはげんじつしゅぎしゃ）は、おけまるによる日本のライトノベル。イラストはさばみぞれが担当している。「小説家になろう」にて2018年12月から連載されており、書籍版がHJ文庫（ホビージャパン）より2020年6月から刊行されている。「HJネット小説大賞2019」大賞受賞作。 メディアミックスとして吉北ぽぷりによる漫画版が『少年エースplus』（KADOKAWA）', 157397) ON CONFLICT DO NOTHING;
