INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1674', 'ダークギャザリング', '2023年夏', 'PR0034', 'TVシリーズ', 25, '『ダークギャザリング』は、近藤憲一による日本の漫画。『ジャンプスクエア』（集英社）において、2019年4月号より連載中。2026年2月時点で累計部数は265万部を突破している。', 152802) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1675', 'ライアー・ライアー', '2023年夏', 'PR0057', 'TVシリーズ', 12, 'ライアー・ライアー  ライアー ライアー - 1997年公開のアメリカ映画。 Liar! Liar! - 1997年リリースのB''zのシングル曲。 ライアー×ライアー - 金田一蓮十郎の漫画。また、それを基にした2021年公開の日本映画。 ライアー・ライアー (小説) - 久追遥希のライトノベル。また、それを基にした漫画および2023年放送のアニメ。', 131863) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1676', 'アンデッドガール・マーダーファルス', '2023年夏', 'PR0079', 'TVシリーズ', 13, '『アンデッドガール・マーダーファルス』は、青崎有吾による日本の小説。カバーイラストは大暮維人。略称は「アンファル」。講談社タイガ（講談社）より2015年12月から刊行されている。', 162983) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1677', 'るろうに剣心 －明治剣客浪漫譚－(2023)', '2023年夏', 'PR0058', 'TVシリーズ', 24, NULL, 142877) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1678', 'はたらく魔王さま！！2nd Season', '2023年夏', NULL, 'TVシリーズ', 12, NULL, 155168) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1679', 'レベル1だけどユニークスキルで最強です', '2023年夏', 'PR0025', 'TVシリーズ', 12, '『レベル1だけどユニークスキルで最強です』（レベルいちだけどユニークスキルでさいきょうです）は、三木なずなによる日本のライトノベル作品。「小説家になろう」にて2017年2月24日から2020年4月19日まで連載。同サイトにて日間、週間、月間、四半期の1位を獲得し、同年8月31日からはKラノベブックス（講談社）より書籍が刊行されている。イラストはすばち。2025年5月時点で電子版を含めたシリーズ累計', 148465) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1680', '英雄教室', '2023年夏', 'PR0073', 'TVシリーズ', 12, '『英雄教室』（えいゆうきょうしつ）は、新木伸による日本のライトノベル。イラストは森沢晴行が担当している。ダッシュエックス文庫（集英社）より2015年1月から刊行されている。2023年7月時点でシリーズ累計発行部数は170万部を突破している。 『ウルトラジャンプ』（集英社）にて水口鷹志によるコミカライズが2015年3月号から同年9月号まで連載された。『月刊少年ガンガン』（スクウェア・エニックス）にて', 139606) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1681', 'うちの会社の小さい先輩の話', '2023年夏', 'PR0019', 'TVシリーズ', 12, '『うちの会社の小さい先輩の話』（うちのかいしゃのちいさいせんぱいのはなし）は、斎創による日本の漫画作品。 大元の作品は作者である斎創がTwitter上で連載した漫画形式の作品。2019年冬のコミックマーケットにて、同人誌と言う形で書籍となる。こちらは下記の商業誌展開後も、電子書籍でも展開している（タイトルに【同人版】が付記されている）。 同人誌頒布の反響が話題となり、竹書房のウェブコミック配信サイ', 155730) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1682', '悲劇の元凶となる最強外道ラスボス女王は民の為に尽くします。', '2023年夏', 'PR0034', 'TVシリーズ', 12, '『悲劇の元凶となる最強外道ラスボス女王は民の為に尽くします。』（ひげきのげんきょうとなるさいきょうげどうラスボスじょおうはたみのためにつくします）は、天壱による日本のライトノベル。イラストは鈴ノ助が担当している。略称は『ラス為』。 小説投稿サイト『小説家になろう』でオンライン小説として、『悲劇の元凶となる最強外道ラスボス女王は民の為に尽くします。〜ラスボスチートと王女の権威で救える人は救いたい〜』', 156040) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1683', 'てんぷる', '2023年夏', 'PR0056', 'TVシリーズ', 12, '『てんぷる』（英語サブタイトル「 No one can live on loneliness」）は、吉岡公威による日本の漫画作品。「コミックDAYS」（講談社）にて2018年9月から配信されている。吉岡初のオリジナル作品であり、2025年4月時点で累計部数は170万部を突破している。 2023年にはテレビアニメ化が決定し、同年7月から9月まで放送された。', 160447) ON CONFLICT DO NOTHING;
