INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1692', 'BanG Dream! It''s MyGO!!!!!', '2023年夏', 'PR0117', 'TVシリーズ', 13, '『BanG Dream! It''s MyGO!!!!!』（バンドリ！イッツマイゴ）は、ブシロードによるメディアミックスプロジェクト『BanG Dream!』を原案としたテレビアニメの一つ。テレビアニメ第1期は2023年6月から9月までTOKYO MXほかにて放送された。 『BanG Dream!』に登場するバンド・MyGO!!!!!を主人公とする本作は、これまでテレビアニメ版『BanG Dream', 163571) ON CONFLICT DO NOTHING;
