INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1695', '幻日のヨハネ -SUNSHINE in the MIRROR-', '2023年夏', 'PR0102', 'TVシリーズ', 13, '『幻日のヨハネ -SUNSHINE in the MIRROR-』（げんじつのヨハネ サンシャイン イン ザ ミラー）は、「ラブライブ!シリーズ」第2作「ラブライブ!サンシャイン!!」の公式スピンオフ作品。略称は「幻ヨハ」。 キャッチコピーは「みんなが知ってるあの子の、みんなが知らない物語――。」', 151513) ON CONFLICT DO NOTHING;
