INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1708', 'アンデッドアンラック', '2023年秋', 'PR0030', 'TVシリーズ', 24, '『アンデッドアンラック』（UNDEAD UNLUCK）は、戸塚慶文による日本の漫画。『週刊少年ジャンプ』（集英社）2019年9号に『アンデッド＋アンラック』のタイトルで読み切りセンターカラーとして掲載された後、2020年8号から2025年9号まで連載された。公式略称は「アンデラ」。 2020年、「次にくるマンガ大賞 2020」にてコミックス部門1位を受賞。2021年6月には「第5回みんなが選ぶTS', 154116) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1709', '君のことが大大大大大好きな100人の彼女', '2023年秋', 'PR0111', 'TVシリーズ', 12, '『君のことが大大大大大好きな100人の彼女』（きみのことがだいだいだいだいだいすきなひゃくにんのかのじょ）は、原作：中村力斗、作画：野澤ゆき子による日本の漫画。『週刊ヤングジャンプ』（集英社）において、2020年4・5合併号から連載中。『少年ジャンプ+』（同社）においても、2020年4月16日から配信されている。略称は「100カノ」。 「負け彼女0の多人数LOVEコメディの新発明・新回答」を謳って', 162694) ON CONFLICT DO NOTHING;
