INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1711', 'ラグナクリムゾン', '2023年秋', 'PR0024', 'TVシリーズ', 24, '『ラグナクリムゾン』（英語: Ragna Crimson）は、小林大樹による日本の漫画作品。『月刊ガンガンJOKER』（スクウェア・エニックス）にて、2017年4月号より連載中。', 146493) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1712', '暴食のベルセルク', '2023年秋', 'PR0150', 'TVシリーズ', 12, NULL, 156039) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1713', '経験済みなキミと、経験ゼロなオレが、お付き合いする話。', '2023年秋', 'PR0052', 'TVシリーズ', 12, '『経験済みなキミと、経験ゼロなオレが、お付き合いする話。』（けいけんずみなキミとけいけんゼロなオレがおつきあいするはなし）は、長岡マキ子による日本のライトノベル。イラストはmagako。富士見ファンタジア文庫（KADOKAWA）より2020年9月から2025年3月まで刊行された。略称は「キミゼロ」。2024年8月時点で電子版を含めたシリーズ累計部数は55万部を突破している。 メディアミックスとして', 154459) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1714', '東京リベンジャーズ 天竺編', '2023年秋', 'PR0058', 'TVシリーズ', 13, NULL, 163329) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1715', 'はめつのおうこく', '2023年秋', 'PR0014', 'TVシリーズ', 12, '『はめつのおうこく』は、yoruhashiによる日本の漫画。ジャンルはダーク・ファンタジー。『月刊コミックガーデン』（マッグガーデン）にて2019年5月号より連載を開始し、同年5月5日からは同社のウェブコミック配信サイト『MAGCOMI』でも配信中。『月刊コミックガーデン』が2026年4月号で休刊した後は『マグコミ』に移籍して連載されている。2023年10月時点で単行本の累計は100万部を突破して', 160900) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1716', '帰還者の魔法は特別です', '2023年秋', 'PR0122', 'TVシリーズ', 12, '『帰還者の魔法は特別です』（きかんしゃのまほうはとくべつです、朝: 귀환자의 마법은 특별해야 합니다、英: A Returner''s Magic Should Be Special）は、Usonanによるウェブ小説。2016年9月2日から2019年8月3日までカカオページにて連載された。また、Wookjakgaによるウェブトゥーンが2018年5月19日からカカオページにて連載されているほか、日本', 163142) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1717', '私の推しは悪役令嬢。', '2023年秋', 'PR0133', 'TVシリーズ', 12, NULL, 158704) ON CONFLICT DO NOTHING;
