INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1724', 'とあるおっさんのVRMMO活動記', '2023年秋', 'PR0025', 'TVシリーズ', 12, '『とあるおっさんのVRMMO活動記』（とあるおっさんのブイアールエムエムオーかつどうき）は、椎名ほわほわによる日本のライトノベルおよびメディアミックス作品。アルファポリスより2014年1月から刊行されている。イラストはヤマーダが担当している。2025年8月時点で電子版を含めたシリーズ累計部数は217万部を突破している。 元々は2013年1月7日に「小説家になろう」で連載を開始した作品。「第6回アル', 161364) ON CONFLICT DO NOTHING;
