INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1729', 'ティアムーン帝国物語～断頭台から始まる、姫の転生逆転ストーリー～', '2023年秋', 'PR0024', 'TVシリーズ', 12, NULL, 154384) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1730', 'ミギとダリ', '2023年秋', 'PR0057', 'TVシリーズ', 13, '『ミギとダリ』は、佐野菜見による日本の漫画作品。『ハルタ』（KADOKAWA）にて、Vol.46からVol.89まで連載された。 1990年の神戸市を舞台に、双子の美少年ミギとダリが養子となった家で起きるサスペンスと、常識や俗世間に疎い2人が巻き起こすシュールギャグが混然一体となった漫画。作者の佐野菜見が2023年8月に急逝した後、同年10月から12月までテレビアニメが放送された。', 142666) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1731', 'MFゴースト', '2023年秋', 'PR0094', 'TVシリーズ', 12, '『MFゴースト』（エムエフゴースト、英語表記:MF GHOST）は、「公道レース」をテーマにした、しげの秀一による日本の漫画作品。 しげのが過去に連載していた『頭文字D』の近未来の世界観という設定で、実在する公道でのレースを題材とした自動車漫画。2024年6月時点で累計部数は500万部を突破している。 「ガソリンエンジンなどの内燃機関自動車が製造中止となり、電気自動車や燃料電池自動車が主流となった', 143327) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1732', '七つの大罪 黙示録の四騎士', '2023年秋', 'PR0066', 'TVシリーズ', 24, NULL, 148862) ON CONFLICT DO NOTHING;
