INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1739', '新しい上司はど天然', '2023年秋', 'PR0001', 'TVシリーズ', 12, '『新しい上司はど天然』（あたらしいじょうしはどてんねん）は、いちかわ暖による日本の漫画。', 165070) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1740', '柚木さんちの四兄弟。', '2023年秋', 'PR0101', 'TVシリーズ', 12, '『柚木さんちの四兄弟。』（ゆずきさんちのよんきょうだい）は、藤沢志月による日本の漫画作品。『ベツコミ』（小学館）にて、2018年9月号より連載中。 第66回小学館漫画賞少女向け部門を受賞した。単行本の累計発行部数は2025年10月時点で200万部を突破している。 メディアミックスとして、2023年10月から12月まで朱夏によるテレビアニメが放送された。2024年5月から7月までテレビドラマがNHK', 164312) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1741', 'アークナイツ 冬隠帰路', '2023年秋', 'PR0047', 'TVシリーズ', 8, NULL, 158895) ON CONFLICT DO NOTHING;
