INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1743', '豚のレバーは加熱しろ', '2023年秋', 'PR0019', 'TVシリーズ', 12, '『豚のレバーは加熱しろ』（ぶたのレバーはかねつしろ）は、逆井卓馬による日本のライトノベル。略称は「豚レバ」。イラストは遠坂あさぎ。第26回電撃小説大賞《金賞》受賞。2020年3月から2024年3月まで電撃文庫（KADOKAWA）より刊行された。2022年12月時点でシリーズ累計部数は25万部を突破している。 メディアミックスとして、みなみによるコミカライズが『電撃マオウ』（同）にて2022年10月', 142599) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1744', '僕らの雨いろプロトコル', '2023年秋', 'PR0124', 'TVシリーズ', 12, '『僕らの雨いろプロトコル』（ぼくらのあめいろプロトコル）は、Quad制作による日本のテレビアニメ作品。2023年10月から12月まで、テレビ朝日系列『NUMAnimation』枠ほかにて放送された。 本作品はeスポーツを舞台に、少年少女たちの青春群像劇が描かれるオリジナル作品である。劇中では埼玉県川越市の風景が描かれている。', 166896) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1745', 'Paradox Live THE ANIMATION', '2023年秋', 'PR0027', 'TVシリーズ', 12, NULL, 150077) ON CONFLICT DO NOTHING;
