INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1755', 'DOG SIGNAL', '2023年秋', NULL, 'TVシリーズ', 20, '『DOG SIGNAL』（ドッグシグナル）は、みやうち沙矢による日本の漫画。『カドコミ』（KADOKAWA）の『COMIC BRIDGE（旧・COMIC BRIDGE online）』レーベルにおいて、2018年7月24日より連載中。新米のドッグトレーナーが成長していく姿を描いた作品。', 160514) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1756', '川越ボーイズ・シング', '2023年秋', NULL, 'TVシリーズ', 12, '『川越ボーイズ・シング』（かわごえボーイズ・シング）は、NBCユニバーサル・エンターテイメント製作による日本のアニメ作品。埼玉県川越市を舞台とする。 2023年3月1日に制作発表され、併せてキャスト、ティザービジュアル、スタッフ、主題歌情報が公開された。3月26日、AnimeJapan 2023のNBCユニバーサルブースにてスペシャルステージが開催。10月から翌年1月までTOKYO MXほかで放送', 162209) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1757', '絆のアリル セカンドシーズン', '2023年秋', 'PR0078', 'TVシリーズ', 12, NULL, 166523) ON CONFLICT DO NOTHING;
