INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1759', 'ビックリメン', '2023年秋', 'PR0136', 'TVシリーズ', 12, '『ビックリメン』(BIKKURI-MEN)は、ロッテのチョコレート菓子『ビックリマン』を題材にした日本のテレビアニメ。2023年10月から12月までTOKYO MXほかにて放送された。 キャッチコピーは「これが、令和のビックリマン」。', 163364) ON CONFLICT DO NOTHING;
